/**
 * Stuff+ page (v4, rebuilt 2026-10-02).
 * Template-driven: reads config from content/stuff_page.json and
 * numbers from content/validation_results.json (generated by
 * tools/build_validation_content.py from diagnostics/stuff_v4/).
 * No number may be typed directly into this file, use the content files.
 *
 * URL query string reflects state: ?season=&pitch=&pitcher=
 * Sections: header, leaderboard, pitcher lookup, pitch-type leaderboard,
 *           under-the-hood (4 cards + version history).
 */

// ──────────────────────────────────────────────────────────── feature labels
const FEATURE_LABELS = {
  release_speed:           "Velocity",
  effective_speed:         "Perceived velocity",
  release_spin_rate:       "Spin rate",
  spin_axis:               "Spin axis",
  hb:                      "Horizontal break",
  ivb:                     "Induced vertical break",
  vaa_residual:            "VAA vs. expected",
  axis_differential:       "Axis differential (SSW proxy)",
  velo_sep_vs_primary_fb:  "Velo sep. vs. own fastball",
  hb_sep_vs_primary_fb:    "H-break sep. vs. own fastball",
  ivb_sep_vs_primary_fb:   "V-break sep. vs. own fastball",
  haa_residual:            "Horiz. approach angle residual",
  pitch_type:              "Pitch type",
  p_throws:                "Pitcher hand",
  stand:                   "Batter stand",
  season:                  "Season",
};
function featureLabel(f) { return FEATURE_LABELS[f] || f; }

// pitch-type display names
const PT_LABELS = {
  FF:"Four-seam (FF)", SI:"Sinker (SI)", FC:"Cutter (FC)", SL:"Slider (SL)",
  ST:"Sweeper (ST)", CU:"Curveball (CU)", CH:"Changeup (CH)", FS:"Split-finger (FS)",
  KN:"Knuckleball (KN)", SV:"Slurve (SV)", SC:"Screwball (SC)",
  FA:"Unclassified FB (FA)", AB:"AB-code (rare)", CS:"CS-code (rare)", FO:"Forkball (FO)",
};
function ptLabel(pt) { return PT_LABELS[pt] || pt; }

// pitch-type colors (CSS-safe)
const PT_COLORS = {
  FF:"#e63946", SI:"#f4a261", FC:"#2a9d8f", SL:"#457b9d", ST:"#6a0572",
  CU:"#264653", CH:"#43aa8b", FS:"#f77f00", KN:"#8d99ae", SV:"#a8dadc",
  SC:"#c77dff", FA:"#adb5bd", AB:"#6c757d", CS:"#dee2e6", FO:"#ffe066",
};
function ptColor(pt) { return PT_COLORS[pt] || "#8d99ae"; }

// ──────────────────────────────────────────────────────────── URL query state
const params = new URLSearchParams(location.search);
function setParam(k, v) {
  if (v == null || v === "") params.delete(k); else params.set(k, String(v));
  const newUrl = location.pathname + (params.toString() ? "?" + params.toString() : "");
  history.replaceState(null, "", newUrl);
}
function getParam(k) { return params.get(k); }

// ──────────────────────────────────────────────────────────── small helpers
function verdictClass(v) {
  if (!v) return "verdict-pending";
  const lo = String(v).toLowerCase();
  if (lo.includes("pass")) return "verdict-pass";
  if (lo.includes("mixed") || lo.includes("pending") || lo.includes("in progress")) return "verdict-mixed";
  if (lo.includes("fail")) return "verdict-fail";
  return "verdict-pending";
}
function notYetRun(obj) {
  return !obj || obj.status === "not_yet_run" || obj.value === null;
}
function displayVal(obj) {
  if (!obj) return "—";
  if (notYetRun(obj)) return "Not yet run";
  if (typeof obj.value === "number") return String(obj.value);
  return obj.value ?? "—";
}
function kv(label, valStr, note) {
  return `<div><span class="kv-label">${label}: </span><span class="kv-val">${valStr}</span>${note ? ` <span class="kv-label" style="font-style:italic;">(${note})</span>` : ""}</div>`;
}

function asteriskSpan(note) {
  return `<span class="sp-asterisk" title="${note}">*</span>`;
}

function muted(s) { return `<span class="muted">${s}</span>`; }

// ──────────────────────────────────────────────────────────── render header
async function renderHeader(cfg, meta) {
  const badgeEl = document.getElementById("sp-version-badge");
  const titleEl  = document.getElementById("sp-title-text");
  const blurbEl  = document.getElementById("sp-opening-blurb");
  const scaleEl  = document.getElementById("sp-scale-statement");
  const footerEl = document.getElementById("sp-meta-footer");

  titleEl.textContent = cfg.title || "Stuff+";
  blurbEl.textContent = cfg.opening_blurb || "";
  scaleEl.textContent = cfg.scale_statement || "";
  renderFeatureBubbles(cfg);

  const status = cfg.stuff_status || "provisional";
  const badge  = status === "validated" ? cfg.version_badge_validated : cfg.version_badge;
  badgeEl.textContent = badge || "v4";
  if (status === "validated") badgeEl.classList.add("validated");

  if (meta) {
    footerEl.textContent =
      `Model: ${meta.display_name || meta.active_version}` +
      (meta.model_hash_sha256 ? ` · hash ${meta.model_hash_sha256.slice(0, 16)}…` : "") +
      (meta.trained_at ? ` · trained ${meta.trained_at.slice(0, 10)}` : "");
  }
}

// ──────────────────────────────────────────────────────────── render leaderboards (overall)
function renderLbList(mountId, entries, onRowClick) {
  const el = document.getElementById(mountId);
  if (!entries || !entries.length) {
    el.innerHTML = `<div class="muted" style="font-size:13px;">No qualified pitchers for this season.</div>`;
    return;
  }
  el.innerHTML = entries.map((e) => {
    const color = e.stuff_plus >= 100 ? "#1a7f37" : "#c9302c";
    const ast   = e.season_asterisk ? asteriskSpan(e.season_note) : "";
    const team  = e.team_abbrev ? muted(` (${e.team_abbrev})`) : "";
    return `<div class="sp-lb-row" tabindex="0" role="button"
        aria-label="${e.name}, Stuff+ ${e.stuff_plus}"
        data-pitcher-id="${e.pitcher_id}" data-name="${e.name || ""}">
      <div class="sp-lb-rank">${e.rank}</div>
      <div class="sp-lb-name">${e.name || "—"}${team}${ast}</div>
      <div class="sp-lb-n">${(e.n_pitches || 0).toLocaleString()} pitches</div>
      <div class="sp-lb-val" style="color:${color}">${e.stuff_plus.toFixed(0)}</div>
    </div>`;
  }).join("");

  el.querySelectorAll(".sp-lb-row").forEach(row => {
    const handler = () => {
      const pid  = Number(row.dataset.pitcherId);
      const name = row.dataset.name;
      if (onRowClick) onRowClick(pid, name);
    };
    row.addEventListener("click", handler);
    row.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") handler(); });
  });
}

async function loadOverallLeaderboard(season, cfg, onRowClick) {
  const captionEl = document.getElementById("sp-lb-caption");
  try {
    const lb = await getJSON(`/api/stuff-model/leaderboard?season=${season}&n=10`);
    renderLbList("sp-lb-top",    lb.top    || [], onRowClick);
    renderLbList("sp-lb-bottom", lb.bottom || [], onRowClick);

    const ast2020 = Number(season) === 2020 ? " <span class='sp-asterisk' title='" + (cfg.season_2020_note || "60-game season") + "'>*</span> 2020: 60-game season, not in training data." : "";
    captionEl.innerHTML =
      (cfg.leaderboard_caption || `Minimum ${cfg.leaderboard_min_pitches || 200} pitches to qualify.`) +
      " KN pitchers score below average by construction. Pitchouts, eephus, unclassified, AB/CS codes excluded." +
      ast2020;

    const fn = document.getElementById("sp-lb-footnotes-top");
    if (fn) fn.innerHTML = "";
  } catch (err) {
    document.getElementById("sp-lb-top").innerHTML    = `<div class="muted">Failed to load.</div>`;
    document.getElementById("sp-lb-bottom").innerHTML = "";
  }
}

// ──────────────────────────────────────────────────────────── pitcher lookup
let _selectedPitcherId = null;
let _selectedPitcherName = "";
let _lookupSeason = 2026;

function renderPitcherSummary(summary, cfg) {
  const score = summary.stuff_plus;
  const color  = score >= 100 ? "#1a7f37" : "#c9302c";
  const ast    = summary.season_asterisk
    ? ` ${asteriskSpan(summary.season_note)}`
    : "";
  const pct    = summary.percentile != null
    ? `<div class="sp-summary-pct">${summary.percentile.toFixed(0)}th percentile among ${summary.n_qualified_in_pool} qualified pitchers</div>`
    : "";
  const unq    = !summary.qualified
    ? `<div class="sp-unqualified">${summary.qualification_note || "Below minimum pitch threshold: score shown but not qualified."}</div>`
    : "";
  return `
    <div class="sp-summary">
      <div>
        <div class="sp-summary-score" style="color:${color}">${score.toFixed(0)}${ast}</div>
        <div style="font-size:13px;color:var(--text-muted);margin-top:4px;">Overall Stuff+ · ${(summary.n_pitches||0).toLocaleString()} pitches · ${summary.season}</div>
        ${pct}${unq}
      </div>
    </div>`;
}

function renderPitchTypeTable(breakdown) {
  if (!breakdown || !Object.keys(breakdown).length) return "<div class='muted'>No pitch data.</div>";
  const rows = Object.entries(breakdown)
    .sort((a,b) => b[1].n_pitches - a[1].n_pitches)
    .map(([pt, d]) => {
      const score = d.stuff_plus;
      const color = score >= 100 ? "#1a7f37" : "#c9302c";
      const usage = d.n_pitches;
      // extract avg velo, ivb, hb from contributions' typical values
      const featMap = {};
      if (d.contributions) {
        d.contributions.forEach(([f, _pts, tv]) => { if (tv !== null && tv !== undefined) featMap[f] = tv; });
      }
      const velo = featMap["release_speed"] != null ? featMap["release_speed"].toFixed(1) : "—";
      const ivb  = featMap["ivb"] != null ? featMap["ivb"].toFixed(1) : "—";
      const hb   = featMap["hb"]  != null ? featMap["hb"].toFixed(1)  : "—";
      const swatch = `<span class="sp-pt-swatch" style="background:${ptColor(pt)}"></span>`;
      return `<tr>
        <td>${swatch}<b>${pt}</b> <span class="muted" style="font-size:11.5px;">${ptLabel(pt).replace(/^.*?\(/, "").replace(")", "")}</span></td>
        <td>${usage.toLocaleString()}</td>
        <td>${velo}</td>
        <td>${ivb}</td>
        <td>${hb}</td>
        <td class="sp-pt-grade" style="color:${color}">${score.toFixed(0)}</td>
      </tr>`;
    }).join("");
  return `<table class="sp-pt-table">
    <thead><tr>
      <th style="text-align:left">Pitch</th>
      <th>Pitches</th>
      <th>Velo</th>
      <th>IVB</th>
      <th>HB</th>
      <th>Stuff+</th>
    </tr></thead>
    <tbody>${rows}</tbody>
  </table>`;
}

function renderCareerTable(career, currentSeason) {
  if (!career || !career.length) return "<div class='muted'>No career data.</div>";
  const rows = career.map(r => {
    const color = r.stuff_plus >= 100 ? "#1a7f37" : "#c9302c";
    const ast   = r.season_asterisk ? asteriskSpan(r.season_note) : "";
    const unq   = !r.qualified ? " (unq.)" : "";
    const isCur = r.season === currentSeason;
    return `<tr class="${isCur ? "sp-career-current" : ""}${!r.qualified ? " sp-unqualified-row" : ""}">
      <td>${r.season}${ast}</td>
      <td style="color:${color};font-weight:${isCur?800:400}">${r.stuff_plus.toFixed(0)}${unq}</td>
      <td>${(r.n_pitches||0).toLocaleString()}</td>
    </tr>`;
  }).join("");
  return `<table class="sp-career-table">
    <thead><tr>
      <th style="text-align:left">Season</th>
      <th>Stuff+</th>
      <th>Pitches</th>
    </tr></thead>
    <tbody>${rows}</tbody>
  </table>
  <div style="font-size:11.5px;color:var(--text-muted);margin-top:6px;">Unqualified rows (unq.) are below 200-pitch minimum.</div>`;
}

function renderShapContributions(breakdown) {
  if (!breakdown || !Object.keys(breakdown).length) return "";
  const sections = Object.entries(breakdown)
    .sort((a,b) => b[1].n_pitches - a[1].n_pitches)
    .map(([pt, d]) => {
      if (!d.contributions || !d.contributions.length) return "";
      const maxAbs = Math.max(...d.contributions.map(([,v]) => Math.abs(v)), 0.01);
      const rows = d.contributions.slice(0, 8).map(([f, pts, tv]) => {
        const halfW = (Math.abs(pts) / maxAbs) * 50;
        const left  = pts >= 0 ? 50 : 50 - halfW;
        const clr   = pts >= 0 ? "#1a7f37" : "#c9302c";
        const tvStr = typeof tv === "number" ? tv.toFixed(2) : (tv === null ? "n/a" : tv);
        return `<div class="shap-row">
          <div class="shap-label">${featureLabel(f)} <span class="muted">(${tvStr})</span></div>
          <div class="shap-track">
            <div class="shap-zero" style="left:50%"></div>
            <div class="shap-bar" style="left:${left}%;width:${halfW}%;background:${clr};"></div>
          </div>
          <div class="shap-val ${pts>=0?"pos":"neg"}">${pts>=0?"+":""}${pts.toFixed(1)}</div>
        </div>`;
      }).join("");
      const swatch = `<span class="sp-pt-swatch" style="background:${ptColor(pt)}"></span>`;
      return `<div style="margin-bottom:16px;">
        <div style="font-size:13px;font-weight:700;color:var(--forest-dark);margin-bottom:8px;">${swatch}${pt}</div>
        ${rows}
      </div>`;
    }).join("");
  return `<div>${sections}<div class="shap-note">Contributions are in Stuff+ points from the model's unshrunk predictions. The sum may differ from (Stuff+−100) by the shrinkage correction.</div></div>`;
}

async function loadPitcherLookup(pitcherId, season, playerName, cfg) {
  const statusEl = document.getElementById("sp-lookup-status");
  const panelEl  = document.getElementById("sp-lookup-panel");
  statusEl.textContent = "Loading…";
  panelEl.innerHTML = "";

  try {
    const [summary, breakdown] = await Promise.all([
      getJSON(`/api/stuff-model/pitcher/${pitcherId}/summary?season=${season}`),
      getJSON(`/api/stuff-model/pitcher/${pitcherId}?season=${season}`),
    ]);
    statusEl.textContent = "";

    panelEl.innerHTML = `
      ${renderPitcherSummary(summary, cfg)}
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:start;margin-bottom:16px;">
        <div>
          <h4 style="font-size:13px;font-weight:700;margin:0 0 8px;">Per-pitch-type breakdown</h4>
          ${renderPitchTypeTable(breakdown)}
        </div>
        <div>
          <h4 style="font-size:13px;font-weight:700;margin:0 0 8px;">Season history</h4>
          <div id="sp-career-mount"><span class="muted" style="font-size:13px;">Loading…</span></div>
        </div>
      </div>
      <details style="margin-top:4px;">
        <summary style="font-size:13px;font-weight:700;cursor:pointer;color:var(--forest-dark);user-select:none;">What drives the grade (feature contributions)</summary>
        <div style="margin-top:10px;">
          ${renderShapContributions(breakdown)}
        </div>
      </details>
    `;

    // Load career and season selector async (non-blocking)
    getJSON(`/api/stuff-model/pitcher/${pitcherId}/career`).then(careerResp => {
      const career = careerResp ? careerResp.seasons : null;
      const careerMount = document.getElementById("sp-career-mount");
      if (careerMount) careerMount.innerHTML = renderCareerTable(career, season);

      if (career) {
        const lsEl = document.getElementById("sp-lookup-season");
        const seasonWrap = document.getElementById("sp-lookup-season-wrap");
        seasonWrap.style.display = "";
        const scoredSeasons = career.map(r => r.season).sort((a,b)=>b-a);
        lsEl.innerHTML = scoredSeasons.map(s => `<option value="${s}"${s===season?" selected":""}>${s}</option>`).join("");
        lsEl.onchange = () => {
          const newSeason = Number(lsEl.value);
          setParam("season", newSeason);
          loadPitcherLookup(pitcherId, newSeason, playerName, cfg);
        };
      }
    }).catch(() => {
      const careerMount = document.getElementById("sp-career-mount");
      if (careerMount) careerMount.innerHTML = "<div class='muted'>Career data unavailable.</div>";
    });

  } catch (err) {
    statusEl.textContent = "No data for this pitcher/season.";
    panelEl.innerHTML = "";
  }
}

// ──────────────────────────────────────────────────────────── pitch-type leaderboard
async function loadPitchTypeLeaderboard(season, pitchType, n, cfg) {
  const topEl    = document.getElementById("sp-pt-lb-top");
  const bottomEl = document.getElementById("sp-pt-lb-bottom");
  const captionEl= document.getElementById("sp-pt-caption");
  const topTitle = document.getElementById("sp-pt-lb-top-title");
  const botTitle = document.getElementById("sp-pt-lb-bottom-title");

  topEl.innerHTML = bottomEl.innerHTML = `<div class="muted" style="font-size:13px;">Loading…</div>`;
  try {
    const lb = await getJSON(`/api/stuff-model/leaderboard?season=${season}&pitch_type=${pitchType}&n=${n}`);
    const count = (lb.top || []).length + (lb.bottom || []).length;
    const label = ptLabel(pitchType);
    topTitle.textContent    = `Top ${(lb.top||[]).length}, ${label}`;
    botTitle.textContent    = `Bottom ${(lb.bottom||[]).length}, ${label}`;

    const noClick = null; // pitch-type lb rows don't trigger lookup
    renderLbList("sp-pt-lb-top",    lb.top    || [], null);
    renderLbList("sp-pt-lb-bottom", lb.bottom || [], null);

    let note = `Minimum ${lb.min_pitches || 100} pitches of type ${pitchType} to qualify.`;
    if (count < 20 && count > 0) note += ` Only ${count} pitchers qualified.`;
    if (!count) note = `No pitchers with ≥ ${lb.min_pitches || 100} ${pitchType} pitches in ${season}.`;
    const ast2020 = Number(season) === 2020 ? " 2020: 60-game season." : "";
    captionEl.textContent = note + ast2020;
  } catch (err) {
    topEl.innerHTML = `<div class="muted">Failed to load.</div>`;
    bottomEl.innerHTML = "";
  }
}

async function populatePitchTypeSelector(season) {
  const sel = document.getElementById("sp-pt-select");
  try {
    const data = await getJSON(`/api/stuff-model/pitch-types?season=${season}`);
    const current = sel.value || getParam("pitch") || "FF";
    sel.innerHTML = (data.pitch_types || [])
      .map(pt => `<option value="${pt.pitch_type}"${pt.pitch_type===current?" selected":""}>${pt.pitch_type} (${pt.n_qualifying_pitchers} qualifiers)</option>`)
      .join("");
    if (!sel.value) sel.value = "FF";
  } catch {
    // fallback — keep existing options
  }
}

function renderEvolution(cfg) {
  const el = document.getElementById("sp-evo-list");
  const items = cfg.version_history && cfg.version_history.items;
  if (!el) return;
  if (!items) { el.innerHTML = "<li>Not available.</li>"; return; }
  el.innerHTML = items.map((it, i) =>
    `<li class="${it.is_current ? "sp-evo-current" : ""}">
      <span class="sp-evo-num">${i + 1}</span>
      <span><span class="vl">${it.version}${it.label ? " (" + it.label + ")" : ""}:</span> ${it.change}</span>
    </li>`
  ).join("");
}

function renderFeatureBubbles(cfg) {
  const el = document.getElementById("sp-bubbles");
  if (!el) return;
  const bubbles = cfg.feature_bubbles || [];
  el.innerHTML = bubbles.map(b => `<span class="sp-bubble">${b}</span>`).join("");
}


// ──────────────────────────────────────────────────────────── init
async function init() {
  const [cfg, meta] = await Promise.all([
    getJSON("content/stuff_page.json"),
    getJSON("/api/stuff-model/meta").catch(() => null),
  ]);

  await renderHeader(cfg, meta);

  // ---- Leaderboard season selector
  const lbSeasonEl = document.getElementById("sp-lb-season");
  const seasons = cfg.available_seasons || [];
  const defaultSeason = Number(getParam("season")) || cfg.default_season || 2026;
  lbSeasonEl.innerHTML = seasons.slice().reverse().map(s =>
    `<option value="${s}"${s===defaultSeason?" selected":""}>${s}</option>`
  ).join("");
  let lbSeason = defaultSeason;

  // callback when a leaderboard row is clicked → load pitcher
  function onLbRowClick(pitcherId, name) {
    _selectedPitcherId = pitcherId;
    _selectedPitcherName = name;
    setParam("pitcher", pitcherId);
    document.getElementById("sp-player-input").value = name;
    const ls = Number(lbSeasonEl.value);
    loadPitcherLookup(pitcherId, ls, name, cfg);
    document.getElementById("sp-lookup-card").scrollIntoView({ behavior: "smooth" });
  }

  await loadOverallLeaderboard(lbSeason, cfg, onLbRowClick);
  lbSeasonEl.addEventListener("change", () => {
    lbSeason = Number(lbSeasonEl.value);
    setParam("season", lbSeason);
    loadOverallLeaderboard(lbSeason, cfg, onLbRowClick);
  });

  // ---- Pitcher lookup search
  const search = createPlayerSearch(
    document.getElementById("sp-player-input"),
    document.getElementById("sp-player-dropdown"),
    async (player) => {
      _selectedPitcherId = player.player_id;
      _selectedPitcherName = player.name;
      setParam("pitcher", player.player_id);
      // use player.latest_season (from players/all) as default; fall back to defaultSeason
      const recentSeason = player.latest_season || defaultSeason;
      const season = Number(getParam("season")) || recentSeason;
      loadPitcherLookup(player.player_id, season, player.name, cfg);
    },
    { roleFilter: "pitcher" }
  );
  await search.load(defaultSeason);

  // Restore pitcher from URL
  const urlPitcherId = getParam("pitcher");
  if (urlPitcherId) {
    const season = Number(getParam("season")) || defaultSeason;
    loadPitcherLookup(Number(urlPitcherId), season, "", cfg);
  } else {
    // restore from PlayerContext
    const remembered = window.PlayerContext && PlayerContext.getCurrent();
    if (remembered && remembered.role === "pitcher") {
      search.setValue(remembered);
      _selectedPitcherId = remembered.player_id;
      loadPitcherLookup(remembered.player_id, defaultSeason, remembered.name, cfg);
    }
  }

  // ---- Pitch-type leaderboard
  const ptSeason = document.getElementById("sp-pt-season");
  ptSeason.innerHTML = seasons.slice().reverse().map(s =>
    `<option value="${s}"${s===defaultSeason?" selected":""}>${s}</option>`
  ).join("");

  await populatePitchTypeSelector(defaultSeason);
  const ptSelect = document.getElementById("sp-pt-select");
  const initPt = getParam("pitch") || ptSelect.value || "FF";
  ptSelect.value = initPt;

  await loadPitchTypeLeaderboard(defaultSeason, initPt, 10, cfg);

  ptSelect.addEventListener("change", () => {
    setParam("pitch", ptSelect.value);
    loadPitchTypeLeaderboard(Number(ptSeason.value), ptSelect.value, 10, cfg);
  });
  ptSeason.addEventListener("change", async () => {
    const s = Number(ptSeason.value);
    setParam("season", s);
    await populatePitchTypeSelector(s);
    loadPitchTypeLeaderboard(s, ptSelect.value, 10, cfg);
  });

  // ---- Evolution
  renderEvolution(cfg);
}

document.addEventListener("DOMContentLoaded", init);
